scripts.rain.txt:
	If ($Event == 146) @Event146;
	Return;
@Event146:
	If ($Zixuan == 20) @sub20;
	Return;
@sub20:	
	BeginRain("Rain2.ini");
	StopMusic();
	Say("路人：下大雨啦，快点躲雨啊！",0);
	Say("居民：快收衣服啊！",0);
	Say("杨影枫：紫轩，这雨好大！我们在这客栈檐下躲躲雨吧！", 2);
	Say("紫轩：也好。", 16);
	SetNpcKind("紫轩", 1);
	PlayerGotoEx(36, 97);
	Sleep(500);
	NpcGoto("紫轩", 36, 96);
	SetPlayerDir(1);
	SetNpcDir("紫轩", 1);
	Say("杨影枫：我们就先在这里避避雨吧！", 2);
	Sleep(500);
	FadeOut();
	Sleep(500);
	Say("几个时辰过去了，雨越下越大，天色已经暗下来，可是雨还没有停的迹象。");
	FadeIn();
	Watch("杨影枫", "紫轩", 0);
	Say("杨影枫：这场雨越下越大，看来今晚是停不了了。", 2);
	Say("紫轩：这可如何是好？天都已经黑了，雨又这么大，怎么回去？ ", 16);
	Say("杨影枫：清平乡离这里路途遥远，下雨后道路泥泞，路上十分危险，不如……", 2);
	Say("紫轩：什么？", 16);
	Say("杨影枫：我们不如今晚就在这家客栈住下，等到明天天亮以后再回清平乡，你看行吗？", 2);
	Say("紫轩：这……也只能如此了！", 16);
	SetNpcKind("紫轩", 3);
	PlayerGoto(37, 87);
	SetPlayerDir(5);
	Sleep(500);
	Say("张胜伟：咦？这不是杨公子吗？",	61);
	Say("杨影枫：你好啊，张老板，我和这位姑娘来惠安镇游玩，不巧遇上大雨，现在天色已晚，想在你这儿暂住一宿，麻烦给我准备两间上房。", 2);
	Say("张胜伟：啊哟不巧，今天的客人特别多，现在只剩下一间上房了。", 61);
	Say("杨影枫：啊？那怎么办？", 2);
	Say("张胜伟：这下雨天，每家客栈估计都是客满，只不过暂住一晚，杨公子和这位姑娘就将就一下吧！", 61);
	Say("紫轩：这……孤男寡女，共处一室，如何使得？", 122);
	Say("张胜伟：姑娘，这位杨公子乃是一个正人君子，难道你信不过他吗？", 61);
	Say("紫轩：……", 17);
	Say("张胜伟：你们再犹豫，躲雨的客人越来越多，恐怕过一会儿连这间房也没了。", 61);
	Say("杨影枫：紫轩，如果你觉得不妥，我可以在房门外过一夜，但是你一个女孩子，总不能露宿街头吧？", 2);
	Say("紫轩：那怎么行？没……没关系，我信得过你。掌柜，我们租下那间房了。", 122);
	FadeOut();
	SetPlayerPos(52, 80);
	SetPlayerDir(7);
	SetPlayerScn();
	SetNpcPos("紫轩", 52, 81);
	SetNpcDir("紫轩", 1);
	SetNpcKind("紫轩", 1);
	Sleep(500);
	FadeIn();
	Say("紫轩：杨大哥，这场雨来得真是古怪啊。", 16);
	Say("杨影枫：老天爷总是和我们开玩笑，好好的天气，突然下起这么大一场雨。", 3);
	Say("紫轩：难道一切都是天意？", 17);
	Say("杨影枫：…… 咳咳 ……，紫轩你看，新买的布都淋湿了。", 3);
	Say("紫轩：我从小就特别害怕下雨天，我娘也是在下雨天去世的……", 20);
	NpcGoto("紫轩", 52， 84);
	SetNpcDir("紫轩", 0);
	Sleep(500);
	PlayerGoto(52, 83);
	SetPlayerDir(1);
	Say("杨影枫：紫轩，你哭了？你是不是想起了你娘？", 2);
	Say("紫轩：我娘是最疼我的人……", 20);
	Say("杨影枫：紫轩，别伤心了。你这么伤心，你娘在九泉之下也不会安心的。其实，你比我要幸福的多，我从来没有见过我娘，她一生下我就去世了。", 2);
	SetNpcDir("紫轩", 5);
	Say("紫轩：杨大哥，对不起，我只顾自己伤心，其实你比我更可怜。", 20);
	Say("杨影枫：没关系，我是男子汉嘛。好了，我们不想这些伤心事了，什么时候有空，请你尝尝我亲手做的叫化鸡，我做的叫化鸡外焦内嫩，香飘十里，绝对一流！", 3);
	Say("紫轩（噗哧一笑）：瞧你的样子，活脱一个自卖自夸的王婆！", 16);
	Say("杨影枫：哈哈，你笑了，你的样子真好看！", 3);
	Say("紫轩：去！油嘴滑舌的，我不理你了！", 122);
	NpcGoto("紫轩", 52, 82);
	SetNpcDir("紫轩", 4);
	Sleep(500);
	PlayerGoto(52, 81);
	SetPlayerDir(1);
	Say("杨影枫：生气啦？你生气的样子更好看！", 3);
	Say("紫轩（脸红）：讨厌！", 122);
	Say("杨影枫：哈哈，怎么又笑了？又哭又笑的……", 3);
	Say("紫轩（轻轻地）：杨大哥，你……喜欢我吗？", 122);
	Say("杨影枫：紫轩，从我在樱花谷第一次见到你的时候，我就已经不再是我自己了，我白天想的是你，夜里梦的也是你，盼着分分秒秒都能见到你！", 120);
	Say("紫轩：那你发誓，永远也不离开我，好吗？", 122);
	Say("杨影枫：紫轩……", 120);
	Say("紫轩：从小到大，爱我的人一个又一个地离开了我，先是我爹，后是我娘，老天可怜我，让我遇见了你，除了我爹娘，你是唯一一个真心喜欢我、对我好的人。我好怕，我真的好怕，怕你也离开我……", 17);
	Say("杨影枫：紫轩，我不会离开你，我又怎么舍得离开你？……", 120);
	Say("紫轩：杨大哥！……", 122);
	FadeOut();
	EndRain();
	Say("一夜过去，雨终于停了。");
	ChangeMapColor(255, 255, 255);
	ChangeAsfColor(255, 255, 255);
	SetNpcPos("张胜伟", 38, 86);
	SetNpcDir("张胜伟", 1);
	SetNpcPos("小叁子", 41, 74);
	SetNpcDir("小叁子", 7);
	SetPlayerPos(37, 87);
	SetPlayerDir(5);
	SetPlayerScn();
	FullLife();
    FullThew();
    FullMana();
	SetNpcPos("紫轩", 37, 86);
	SetNpcDir("紫轩", 5);
	SetNpcKind("紫轩", 3);
	PlayMusic("mc003.mp3");
	FadeIn();
	Watch("张胜伟", "杨影枫", 0);
	Say("张胜伟：杨公子昨晚休息得可好？", 61);
	Say("杨影枫：很好，多谢关心。", 2);
	Say("张胜伟：不再多住几日了？", 61);
	Say("杨影枫：不了，我要送这位姑娘回家，改日再来拜访吧。", 2);
	Say("张胜伟：随时来随时欢迎，卓庄主的朋友就是我张某的朋友。杨公子和这位姑娘慢走！", 61);
	Say("杨影枫：（……）紫轩，咱们走吧！", 7);
	PlayerGoto(34, 95);
	SetPlayerDir(1);
	Sleep(500);
	Say("紫轩：杨大哥，怎么啦？", 16);
	Watch("杨影枫", "紫轩", 0);
	Say("杨影枫：我想起一件事，要问问这里的一位朋友。", 2);
	Say("紫轩：什么事？", 16);
	Say("杨影枫：我初来惠安镇的时候，也是投宿在这家客栈，期间结识了一位张仲天张大哥。这位张大哥在我落难之际帮过我，可是他却在某天夜里被人暗害，死得不明不白……", 2);
	Say("紫轩：啊！……", 17);
	Say("杨影枫：张兄于我有恩，我怎能让他冤死？", 2);
	Say("紫轩：不错，滴水之恩，自当涌泉相报。",	16);
	Say("杨影枫：紫轩，还是你知我心意！所以我想向这里的一位小二打听一下，看看能否探知张兄的死因。",	2);
	Say("紫轩：好，我同你一起去。",	16);
	PlayerGoto(37, 80);
	PlayerGoto(40, 75);
	SetPlayerDir(5);
	Say("杨影枫：小叁子，还记得我吗？", 2);
	SetNpcDir("小叁子", 1);
	Say("小叁子：你是……杨公子！啊，近来可好？", 64);
	Say("杨影枫：很好，小叁子，我想向你打听点事。", 2);
	Say("小叁子：什么事？", 64);
	Say("杨影枫：你还记得那个叫张仲天的客人吗？", 2);
	Say("小叁子：记得记得，不就是那个在夜里被人害了的张仲天吗？", 64);
	Say("杨影枫：不错，就是他，你后来可有听到什么关于他死因的消息？",2);
	Say("小叁子：没太留意，不过如果杨公子关心，我可以帮你打听打听。", 64);
	Say("杨影枫：那就多谢了！", 2);
	Say("小叁子：不必客气，有消息我自然会告诉你。", 64);
	Say("杨影枫：好，如此拜托了！", 2);
	SetNpcDir("小叁子", 7);
	Watch("杨影枫", "紫轩", 0);
	Say("杨影枫：紫轩，我们回清平乡吧。", 2);
	Say("紫轩：好的。", 16); 
	PlayerGoto(34, 95);
	SetPlayerDir(1);
	//Assign($Zixuan, 30);
	//Assign($Event, 148);
	Memo("送紫轩回清平乡。");
	SetMapTrap(16, "");
	//SetMapTrap(1, "Trap01.txt");
	//SetMapTrap(2, "Trap02.txt");
	//SetMapTrap(3, "Trap03.txt");
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("mc015.mp3");
	Say("杨影枫送紫轩从惠安镇回到了清平乡。");
	LoadMap("map_022_清平乡.map");

	LoadNpc("qingpingxiang.npc");
	LoadObj("map022_obj.obj");

	If ($QiGaiPos == 1) @QiGaiPos31;
	If ($QiGaiPos == 2) @QiGaiPos32;
	@QiGaiPos31:
		SetNpcPos("乞丐", 54, 62);
		Goto @QiGaiPos3End;
	@QiGaiPos32:
		SetNpcPos("乞丐", 0, 0);
		Goto @QiGaiPos3End;
	@QiGaiPos3End:

	SetPlayerPos(76, 18);
	SetPlayerDir(1);
	EnableNpcAI();
	FadeIn();
	Assign($Event, 150);
	Return;

