scripts.巧遇紫轩.txt:
	If ($Event == 1820) @1820;
	If ($Event == 800) @800;

@1820:	
	StopMusic();
	DelNpc("紫轩");
	DelNpc("张仲天");
	AddNpc("紫轩.ini",36,24,3);
	AddNpc("张仲天.ini",2,73,7);
	SetNpcKind("张仲天",0);
	SetNpcActionFile("张仲天",0,"mpc166-1.asf");
	SetNpcActionFile("张仲天",1,"mpc166-1.asf");
	Say("杨影枫：紫轩！",4);
	Say("紫轩：杨大哥！",16);
	NpcGotoEx("紫轩",34,21);
	PlayerRunTo(34,20);
	Watch("紫轩","杨影枫",0);
	PlayMusic("mc013.mp3");
	Say("杨影枫：紫轩！你怎么会在这里？",4);
	Say("紫轩：杨大哥！我正在到处找你呢！",16);
	Say("杨影枫：发生什么事了？",4);
	Say("紫轩：杨大哥！我带你去见一个人。",16);
	Say("杨影枫：谁？",4);
	Say("紫轩：时间紧急，去了你就知道了。",16);

	FadeOut();
	SetPlayerPos(3,74);
	SetPlayerDir(3);
	SetNpcPos("紫轩",3,71);
	SetNpcDir("紫轩",2);
	SetNpcPos("蔷薇",2,75);
	SetNpcDir("蔷薇",4);
	FadeIn();

	Say("杨影枫：原来是张兄，你不是已经……",4);
	Say("张仲天：杨兄，上次在客栈之时，我被卓非凡盯上，不得不诈死脱身，我给你的秘笈实际上是一本假的。",52);
	Say("杨影枫：在下已经知道了，你的那本假秘笈害我好惨哪。",2);
	Say("张仲天：我如今死期将至，还望杨兄能原谅在下。",52);
	Say("杨影枫：张兄放心，此事我不会放在心上的！",2);
	Say("张仲天：多谢杨兄大量，不见怪于我，咳……除此之外，我还有一事要告知杨兄，此事与杨兄关系重大！",52);
	Say("杨影枫：张兄请说。",2);
	Say("张仲天：杨兄可知我乃魔教中人？",52);
	Say("杨影枫：哦？张兄原来是忘忧教中人。",4);
	Say("张仲天：魔教教主纳兰潜凛早年在中原武林散布关于《武道德经》的谣言，意在挑起中原武林的纷争，为魔教再次进入中原做准备。",52);
	Say("杨影枫：又是纳兰潜凛。",2);
	Say("张仲天：日前教主他不知从何处得到了一本真正的《武道德经》，被在下无意中发现，他为了不使秘密泄漏，就想杀我灭口……",52);
	Say("杨影枫：啊！原来是他？他怎的连自己的亲生女儿都不放过？",4);
	Say("张仲天：在下对教主一片忠心，他仍不肯放过，虽是我自作自受，却着实不甘……",52);
	Say("杨影枫：张兄……",2);
	Say("张仲天：魔教目前在中原的势力已经越来越大，杨兄也是教主要对付的主要目标，请杨兄多……小……心……",52);
	
	SetNpcDir("张仲天", 0);
	NpcSpecialAction("张仲天","mpc166-2.asf");
	SetNpcRes("张仲天", "npc082-张仲天死啦.ini");
	Sleep(3000);
	
	Watch("杨影枫","紫轩",0);
	Watch("蔷薇","杨影枫",1);
	Say("杨影枫：紫轩，多谢你通知我。",2);
	Say("紫轩：大哥何必客气？对了，上回真儿姑娘找到了吗？",16);
	Say("杨影枫：找到了，不过绑架她的并不是飞龙堡的人，多半是魔教中人。",2);
	Say("紫轩：啊？看来魔教是想挑拨你和飞龙堡之间的关系，然后从中渔利。",16);
	Say("杨影枫：想必如此。后来真儿又被一个假扮蔷薇她爹的人打伤。",2);
	Say("蔷薇：我们就是刚调查了此事回来。", 29);
	Watch("蔷薇","杨影枫",0);	
	Say("杨影枫：薇儿，在天星道长证实你爹的清白之后，我便开始怀疑纳兰潜凛了，只是还不敢确定，毕竟虎毒不食子，现在看来，多半不会错了。",2);
	Say("蔷薇：影枫哥，你是说纳兰潜凛假扮我爹，抢走了秘笈并且打伤了真儿姐？",29);
	Say("杨影枫：必定如此。",2);
	Say("蔷薇：那真儿姐和眉儿姐现在岂不是很危险？我们赶紧回忘忧岛吧！",29);
	Say("紫轩：那你们快去吧！",16);
	Say("杨影枫：嗯……，可是张大哥的后事……",2);
	Say("紫轩：杨大哥，真儿姐和眉儿姐需要你，你快走吧。张大哥的后事就交给我找人来料理了。",16);
	Say("杨影枫：这也好。那……紫轩……你多保重……",2);
	
	Memo("回忘忧岛看纳兰真");
	Assign($Event,1821);
	Return;

