scripts.紫轩对话.txt:
	If ($Event == 146) @Event146;
	If ($Event == 170) @Label1;
	If ($Event == 1821) @Event1821;
	Goto @end;

@Event146:
	If ($Zixuan == 0) @sub1;
	If ($Zixuan == 10) @sub2;
	If ($Zixuan == 20) @sub3;
	If ($Zixuan == 30) @sub4;
	Return;
	
@sub1:
	If ($Talkzx0121 == 0) @Talk0;
	If ($Talkzx0121 == 1) @Talk1;
	If ($Talkzx0121 == 2) @Talk2;
	If ($Talkzx0121 == 3) @Talk3;
	Goto @end;
@Talk0:
	Say("紫轩：惠安镇真是一个繁华的地方。", 16);
	Say("杨影枫：是啊。", 3);	
	Assign($Talkzx0121, 1);
	Return;
@Talk1:	
	Say("杨影枫：镇上最大的酒楼就是醉仙楼。",3);
	Say("紫轩：你听过那个歌女唱过歌吗？", 16);
	Say("杨影枫：没有，不过我听说她最擅长的歌叫做《天仙子》，唱得声情两绝。",3);
	Say("紫轩：那我们快点去醉仙楼听歌吧！", 16);
	Say("杨影枫：好！", 3);
	Assign($Talkzx0121, 2);
	Return;
@Talk2:	
	Say("紫轩：杨公子……", 16);
	Say("杨影枫：叫我杨大哥吧！", 3);
	Say("紫轩：杨……大哥，陪我一个女孩子逛街，你会不会觉得闷啊？", 16);
	Say("杨影枫：美人在侧，怎么会闷呢？街上的那些小伙子不知道有多羡慕我呢！", 3);
	Say("紫轩（抿嘴一笑）：臭美！", 122);
	Assign($Talkzx0121, 3);
	Return;
@Talk3:
	Say("杨影枫：紫轩，惠安镇上的姑娘虽多，可我看来看去，没有一个比得上你！", 3);
	Say("紫轩：不会吧？我倒是觉得那些姑娘都很漂亮喔！", 122); 
	Return;	

@sub2:
	If ($Talkzx0122 == 0) @Talk4;
	If ($Talkzx0122 == 1) @Talk5;
	If ($Talkzx0122 == 2) @Talk6;
	If ($Talkzx0122 == 3) @Talk7;
	Goto @end;
@Talk4:
	Say("杨影枫：紫轩，你穿红颜色真好看。", 3);
	Say("紫轩：怎么会？红色是大俗之色，正好配我这种俗人罢了。", 122);
	Say("杨影枫：你若是俗人，天下就没有清雅之人了。", 3);	
	Assign($Talkzx0122, 1);
	Return;
@Talk5:	
	Say("杨影枫：紫轩，你累不累？要不要找家茶馆歇会儿？", 2);
	Say("紫轩：不用，我不累，先四处逛逛吧。", 16);
	Assign($Talkzx0122, 2);
	Return;
@Talk6:	
	Say("杨影枫：紫轩，你以后心情郁闷的时候，可以找我陪你到街上散散心，这样就会开心多了。", 3);
	Say("紫轩：杨大哥，你对我真好！", 122);
	Say("杨影枫：别这么说，我都不好意思了！", 120);
	Say("紫轩：杨大哥，我们到桥上看看风景吧！", 16);
	Assign($Talkzx0122, 3);
	Return;
@Talk7:
	Say("杨影枫：镇上有卖花的姑娘，自古鲜花配美人，我去买些花来给你带吧。", 3);
	Assign($Talkzx0122, 0);
	Return;	

@sub3:
	If ($Talkzx0123 == 0) @Talk8;
	If ($Talkzx0123 == 1) @Talk9;
	If ($Talkzx0123 == 2) @Talk10;
	If ($Talkzx0123 == 3) @Talk11;
	Goto @end;
@Talk8:
	Say("紫轩：杨大哥，你平时除了练剑，还喜欢做些什么？", 16);
	Say("杨影枫：我这个人笨手笨脚，除了武功简直一无所长，不过，我会做叫化鸡！", 3);
	Say("紫轩：叫化鸡？！", 16);
	Say("杨影枫：是啊，我十岁那年，有一次嘴馋去偷人家院子里的鸡，被一个九个指头的乞丐撞到，他狠狠教训了我一顿，不过后来却教会了我做叫化鸡。", 3);
	Say("紫轩：哈哈，原来你小时候这么调皮。", 16);
	Assign($Talkzx0123, 1);
	Return;
@Talk9:	
	Say("杨影枫：紫轩，你怎么会到樱花谷吹萧的？", 2);
	Say("紫轩：我心情愁烦的时候喜欢一个人四处走走，一次无意中发现了樱花谷，我喜爱那里的幽静，所以常去那里吹萧，一段日子不去，我还会不习惯呢。", 16);
	Assign($Talkzx0123, 2);
	Return;
@Talk10:	
	Say("杨影枫：紫轩，你我本来没有可能在樱花谷相遇，可是却偏偏在那里相遇了，难道这真的是上天注定？", 120);
	Say("紫轩：聚散不由人，杨公子，如今你在芭蕉小筑只是暂住，总有一天你会离开那里的，到时我们还不是要分开？", 16);
	Say("杨影枫：紫轩……", 2);
	Assign($Talkzx0123, 3);
	Return;
@Talk11:
	Say("紫轩：杨大哥，如果你日后遇到了别的女孩，会不会忘了我？", 16);
	Say("杨影枫：不会！我怎么也不会忘了你的，相信我，紫轩！", 2);
	Return;	

@sub4:
	If ($Talkzx0124 == 0) @Talk12;
	If ($Talkzx0124 == 1) @Talk13;
	If ($Talkzx0124 == 2) @Talk14;
	If ($Talkzx0124 == 3) @Talk15;
	Goto @end;
@Talk12:
	Say("紫轩：杨大哥，如果你以后遇到了比我好的女孩，会不会不理我？", 16);
	Say("杨影枫：紫轩，你放心，我决不会做对不起你的事！", 3);
	Assign($Talkzx0124, 1);
	Return;
@Talk13:	
	Say("紫轩：杨大哥，我真的好想能够永远和你在一起，只是……世事难料，谁也不知道明天会发生些什么。", 17);
	Say("杨影枫：紫轩，何必杞人忧天呢？只要你愿意，我也愿意，我们就可以永远在一起。", 3);
