	Say("酒鬼：咳…咳…，真是不懂！人常言：饮酒能解千千愁。可是我老汉早喝晚饮的，喝到了最后，我的忧愁却反而越加重了。");
	Say("杨影枫：老人家，何必天天在此饮酒，何必自寻烦恼呢？老人家，你有什么痛楚吗？",2);
	Say("酒鬼：唉，别提过去了。");
	Say("酒鬼：唉……，二十年前因为自已的一念之差……呜…");
	Say("酒鬼：…曾经…，有一份真挚的爱情放在我面前，我没有去珍惜，等到我失去的时候方知后悔……");
	Say("酒鬼：没想到，人世间最大的痛苦就在于此……");
	Say("酒鬼：……唉……！");
	Say("酒鬼：如果老天能让我回到二十年之前的话，……我只想对那个故人说……");
	Say("酒鬼：呜……我喜……喜欢你…");
	Say("酒鬼：呜……");
	Assign($DrinkMan,1);
	Return;

@HaveTalk:
	Say("酒鬼：呜！……秀…秀…莲…呀！");
	Say("酒鬼：狗屎我…二十年前……对不起你呀……！我知道…错了……");
	Say("酒鬼：……你回来吧……，我再也不喝酒了……");
	Return;
	
@Talk2:	
	If ($DrinkMan1 == 1) @HaveTalk1;
	Say("酒鬼：……呜……");
	Say("酒鬼：秀莲！秀莲！你回来呢！你回到我身边呢！");
	Say("纳兰真：嗯？"，9);
	Watch("杨影枫","纳兰真",0);
	Say("杨影枫：真儿，你从前认识他吗？",2);
	Say("纳兰真：……，我不认识他呀。",9);
	Watch("酒中仙","ALLPLAYER",1);
	Say("杨影枫：老人家，你看错人了，她并不认识你。",2);
	Say("酒鬼：……唉……，老了，眼花了…，唉……。");
	Assign($DrinkMan1,1);
	Return;

@HaveTalk1:
	Say("酒鬼：……秀莲……，你在哪里呀？…");	
	Say("酒鬼：你到底是嫁给谁了……");
	Return;

