	Goto @end;


@Event957:
	Talk(82300, 82350);
//	Say("小叁子：前些天有群江湖人物在我们这儿住店，后来我有时候回家，在路上常碰到那群人中的人物，不知他们在倚天山那一带干什么，难道是那一带有什么宝贝？我有机会得问问我娘。", 64);
//	Assign($Event96GetMsg3, 1);
