@Sub2500:
	Say("小叁子：去去去！离我远点，我都快烦死啦！", 64);
	Say("杨影枫：怎么如此讲话！", 2);
	Say("小叁子：哦，公子，过意不去。我确实有烦事，不知公子可否帮我？", 64);
	Say("杨影枫：嗯，好吧，请说。", 2);
	Say("小叁子：我昨日和表妹因一小事吵翻啦，想去和她道歉，又怕她不理我。想劳烦公子帮我把这封信送予她。不知可否？", 64);
	Say("杨影枫：好，不知如何送到？", 2);
